import React, { useState, useEffect } from "react";
import "./Dashboard.css";

function Dashboard({ userData, updateUserData }) {
  const [showProfile, setShowProfile] = useState(false);
  const [editData, setEditData] = useState(userData);

  const [file, setFile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [type, setType] = useState("");
  const [darkMode, setDarkMode] = useState(false);

  // PROFILE EDIT HANDLER
  const handleProfileChange = (key, value) => {
    setEditData({
      ...editData,
      [key]: value
    });
  };

  const saveProfile = () => {
    updateUserData(editData);
    setShowProfile(false);
  };

  return (
    <div className={`dashboard-main ${darkMode ? "dark" : ""}`}>
      <div className="container">

        {/* NAVBAR */}
        <div className="navbar">
          <div className="logo">FinSight</div>

          <div style={{ display: "flex", gap: "15px", alignItems: "center" }}>
            
            {/* PROFILE ICON */}
            <div
              onClick={() => setShowProfile(true)}
              style={{
                width: "35px",
                height: "35px",
                borderRadius: "50%",
                background: "linear-gradient(135deg, #1e3c72, #2a5298)",
                color: "white",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                cursor: "pointer",
                fontWeight: "600"
              }}
            >
              👤
            </div>

            <div
              className={`theme-circle ${darkMode ? "dark" : "light"}`}
              onClick={() => setDarkMode(!darkMode)}
            ></div>
          </div>
        </div>

        {/* HERO */}
        <div className="hero">
          <h1>Welcome Back 👋</h1>
          <p>Your financial dashboard is ready</p>
        </div>

        {/* PROFILE PANEL */}
        {showProfile && (
          <div style={{
            position: "fixed",
            right: "20px",
            top: "80px",
            width: "320px",
            background: "white",
            padding: "20px",
            borderRadius: "16px",
            boxShadow: "0 10px 30px rgba(0,0,0,0.2)",
            zIndex: 999
          }}>
            <h3>Profile</h3>

            <div style={{ marginTop: "15px" }}>
              <label>Income Type</label>
              <input
                value={editData.income || ""}
                onChange={(e) =>
                  handleProfileChange("income", e.target.value)
                }
                style={{ width: "100%", marginTop: "5px", padding: "8px" }}
              />
            </div>

            <div style={{ marginTop: "15px" }}>
              <label>Priorities</label>
              <input
                value={(editData.priorities || []).join(", ")}
                onChange={(e) =>
                  handleProfileChange("priorities", e.target.value.split(","))
                }
                style={{ width: "100%", marginTop: "5px", padding: "8px" }}
              />
            </div>

            <div style={{ marginTop: "15px" }}>
              <label>Budget Limits</label>
              <textarea
                value={JSON.stringify(editData.limits || {}, null, 2)}
                onChange={(e) =>
                  handleProfileChange("limits", JSON.parse(e.target.value || "{}"))
                }
                style={{ width: "100%", marginTop: "5px", padding: "8px" }}
              />
            </div>

            <button
              onClick={saveProfile}
              style={{ marginTop: "15px", width: "100%" }}
            >
              Save Changes
            </button>
          </div>
        )}

        {/* DASHBOARD CONTENT */}
        <div style={{ marginTop: "40px" }}>
          <h3>Your Preferences</h3>

          <p><strong>Income:</strong> {userData.income}</p>
          <p><strong>Priorities:</strong> {(userData.priorities || []).join(", ")}</p>
        </div>

      </div>
    </div>
  );
}

export default Dashboard;
